// This file will be auto-generated by graphql-codegen when backend is running.
// For now, define types manually to match the schema.

import { gql } from '@apollo/client';
import * as Apollo from '@apollo/client';

export enum Priority {
  HIGH = 'HIGH',
  MEDIUM = 'MEDIUM',
  LOW = 'LOW',
}

export enum TaskStatus {
  TODO = 'TODO',
  IN_PROGRESS = 'IN_PROGRESS',
  DONE = 'DONE',
}

export interface Subject {
  __typename?: 'SubjectModel';
  id: string;
  name: string;
  color: string;
  order: number;
  units: Unit[];
}

export interface Unit {
  __typename?: 'UnitModel';
  id: string;
  name: string;
  order: number;
  subjectId: string;
}

export interface Task {
  __typename?: 'TaskModel';
  id: string;
  title: string;
  description?: string | null;
  priority: Priority;
  status: TaskStatus;
  startDate: string;
  dueDate: string;
  completedAt?: string | null;
  subjectId: string;
  unitId?: string | null;
  subject: Pick<Subject, 'id' | 'name' | 'color'>;
  unit?: Pick<Unit, 'id' | 'name'> | null;
  createdAt: string;
  updatedAt: string;
}

export interface Streak {
  __typename?: 'StreakModel';
  id: string;
  currentStreak: number;
  longestStreak: number;
  lastCompletionDate?: string | null;
}

export interface TemplateItem {
  __typename?: 'TemplateItemModel';
  id: string;
  title: string;
  description?: string | null;
  subjectName: string;
  unitName?: string | null;
  priority: Priority;
  dayOffset: number;
  durationDays: number;
}

export interface Template {
  __typename?: 'TemplateModel';
  id: string;
  name: string;
  description?: string | null;
  userId: string;
  items: TemplateItem[];
  createdAt: string;
}

export interface TaskFilterInput {
  subjectId?: string | null;
  unitId?: string | null;
  priority?: Priority | null;
  status?: TaskStatus | null;
}

// Queries
export const GET_SUBJECTS = gql`
  query GetSubjects {
    subjects {
      id
      name
      color
      order
      units {
        id
        name
        order
        subjectId
      }
    }
  }
`;

export const GET_TASKS = gql`
  query GetTasks($filter: TaskFilterInput) {
    tasks(filter: $filter) {
      id
      title
      description
      priority
      status
      startDate
      dueDate
      completedAt
      subjectId
      unitId
      subject { id name color }
      unit { id name }
      createdAt
      updatedAt
    }
  }
`;

export const GET_TODAY_TASKS = gql`
  query GetTodayTasks {
    todayTasks {
      id
      title
      description
      priority
      status
      startDate
      dueDate
      subject { id name color }
      unit { id name }
    }
  }
`;

export const GET_UPCOMING_DEADLINES = gql`
  query GetUpcomingDeadlines($withinHours: Float!) {
    upcomingDeadlines(withinHours: $withinHours) {
      id
      title
      dueDate
      priority
      subject { name color }
    }
  }
`;

export const GET_MY_STREAK = gql`
  query GetMyStreak {
    myStreak {
      id
      currentStreak
      longestStreak
      lastCompletionDate
    }
  }
`;

export const GET_TEMPLATES = gql`
  query GetTemplates {
    templates {
      id
      name
      description
      items {
        id
        title
        subjectName
        unitName
        priority
        dayOffset
        durationDays
      }
      createdAt
    }
  }
`;

// Mutations
export const CREATE_TASK = gql`
  mutation CreateTask($input: CreateTaskInput!) {
    createTask(input: $input) {
      id
      title
      description
      priority
      status
      startDate
      dueDate
      subjectId
      unitId
      subject { id name color }
      unit { id name }
    }
  }
`;

export const UPDATE_TASK = gql`
  mutation UpdateTask($id: String!, $input: UpdateTaskInput!) {
    updateTask(id: $id, input: $input) {
      id
      title
      description
      priority
      status
      startDate
      dueDate
      completedAt
      subjectId
      unitId
      subject { id name color }
      unit { id name }
    }
  }
`;

export const DELETE_TASK = gql`
  mutation DeleteTask($id: String!) {
    deleteTask(id: $id) { id }
  }
`;

export const CREATE_TEMPLATE = gql`
  mutation CreateTemplate($input: CreateTemplateInput!) {
    createTemplate(input: $input) {
      id
      name
      description
      items {
        id
        title
        subjectName
        unitName
        priority
        dayOffset
        durationDays
      }
    }
  }
`;

export const DELETE_TEMPLATE = gql`
  mutation DeleteTemplate($id: String!) {
    deleteTemplate(id: $id) { id }
  }
`;

export const APPLY_TEMPLATE = gql`
  mutation ApplyTemplate($input: ApplyTemplateInput!) {
    applyTemplate(input: $input) {
      id
      title
      subject { name }
    }
  }
`;

// Hooks
export function useGetSubjectsQuery(options?: Apollo.QueryHookOptions) {
  return Apollo.useQuery<{ subjects: Subject[] }>(GET_SUBJECTS, options);
}

export function useGetTasksQuery(options?: Apollo.QueryHookOptions<{ tasks: Task[] }, { filter?: TaskFilterInput }>) {
  return Apollo.useQuery<{ tasks: Task[] }, { filter?: TaskFilterInput }>(GET_TASKS, options);
}

export function useGetTodayTasksQuery(options?: Apollo.QueryHookOptions) {
  return Apollo.useQuery<{ todayTasks: Task[] }>(GET_TODAY_TASKS, options);
}

export function useGetUpcomingDeadlinesQuery(options?: Apollo.QueryHookOptions<{ upcomingDeadlines: Task[] }, { withinHours: number }>) {
  return Apollo.useQuery<{ upcomingDeadlines: Task[] }, { withinHours: number }>(GET_UPCOMING_DEADLINES, options);
}

export function useGetMyStreakQuery(options?: Apollo.QueryHookOptions) {
  return Apollo.useQuery<{ myStreak: Streak }>(GET_MY_STREAK, options);
}

export function useGetTemplatesQuery(options?: Apollo.QueryHookOptions) {
  return Apollo.useQuery<{ templates: Template[] }>(GET_TEMPLATES, options);
}

export function useCreateTaskMutation(options?: Apollo.MutationHookOptions) {
  return Apollo.useMutation(CREATE_TASK, options);
}

export function useUpdateTaskMutation(options?: Apollo.MutationHookOptions) {
  return Apollo.useMutation(UPDATE_TASK, options);
}

export function useDeleteTaskMutation(options?: Apollo.MutationHookOptions) {
  return Apollo.useMutation(DELETE_TASK, options);
}

export function useCreateTemplateMutation(options?: Apollo.MutationHookOptions) {
  return Apollo.useMutation(CREATE_TEMPLATE, options);
}

export function useDeleteTemplateMutation(options?: Apollo.MutationHookOptions) {
  return Apollo.useMutation(DELETE_TEMPLATE, options);
}

export function useApplyTemplateMutation(options?: Apollo.MutationHookOptions) {
  return Apollo.useMutation(APPLY_TEMPLATE, options);
}
